#!/usr/bin/env bash
# RStudio Server sign-in check (rserver.conf auth-pam-helper-path; spec §13.3). rserver runs it as
#   rstudio-auth <user> <pam service> <prompt flag>     with the typed password on stdin;
# exit 0 = signed in, anything else = refused. ONLY user `agent`, and ONLY the password in the owner's
# per-project FILE (generated by agent-up, mounted read-only); never an environment variable.
# Fails closed: no file, an unreadable or short file, or an empty password all refuse.
set -uo pipefail
PWFILE=/run/secrets/rstudio-password
[ "${1:-}" = agent ] || exit 1
want=$(cat "$PWFILE" 2>/dev/null) || exit 1
[ "${#want}" -ge 16 ] || exit 1
got=$(cat) || exit 1
[ -n "$got" ] && [ "$got" = "$want" ] || exit 1
exit 0
